export class JobLeaseTable{constructor(){this.map=new Map();this.seq=0} acquire(key,owner,{now=Date.now(),ttlMs=30000}={}){const cur=this.map.get(key);if(cur&&cur.expiresAt>now&&cur.owner!==owner)return {acquired:false,current:cur};const token=++this.seq;const lease={key,owner,token,acquiredAt:now,expiresAt:now+ttlMs};this.map.set(key,lease);return {acquired:true,lease}} renew(key,owner,token,{now=Date.now(),ttlMs=30000}={}){const cur=this.map.get(key);if(!cur||cur.owner!==owner||cur.token!==token||cur.expiresAt<=now)throw new Error('LEASE_FENCED');const lease={...cur,expiresAt:now+ttlMs};this.map.set(key,lease);return lease} release(key,owner,token){const cur=this.map.get(key);if(!cur||cur.owner!==owner||cur.token!==token)return false;this.map.delete(key);return true}}
export function acceptFencingToken(lastToken,candidateToken){return Number(candidateToken)>Number(lastToken||0)}
